"""Vibrating-string harmonics.

Wave speed:      c = sqrt(T / mu)
Frequencies:     f_n = n * c / (2 * L),  n = 1, 2, 3, ...
"""

import math


def wave_speed(tension: float, mu: float) -> float:
    """c = sqrt(T / mu)."""
    if tension <= 0:
        raise ValueError("tension must be > 0")
    if mu <= 0:
        raise ValueError("mu must be > 0")
    return math.sqrt(tension / mu)


def fundamental_frequency(tension: float, length: float, mu: float) -> float:
    """f_1 = c / (2 L) = sqrt(T/mu) / (2L)."""
    if length <= 0:
        raise ValueError("length must be > 0")
    return wave_speed(tension, mu) / (2.0 * length)


def frequencies(tension: float, length: float, mu: float, n_max: int = 6):
    """First n_max harmonic frequencies f_n = n * f_1."""
    f1 = fundamental_frequency(tension, length, mu)
    return [n * f1 for n in range(1, n_max + 1)]


def tension_for_pitch(f1: float, length: float, mu: float) -> float:
    """Tension required to tune a string to f1: T = mu * (2 L f1)^2."""
    if length <= 0:
        raise ValueError("length must be > 0")
    if mu <= 0:
        raise ValueError("mu must be > 0")
    if f1 <= 0:
        raise ValueError("f1 must be > 0")
    return mu * (2.0 * length * f1) ** 2


if __name__ == "__main__":
    # Guitar low E string
    L = 0.648          # m
    mu = 5.4e-3        # kg/m
    f1_target = 82.41  # Hz

    T = tension_for_pitch(f1_target, L, mu)
    harm = frequencies(T, L, mu, n_max=6)

    print(f"Low E string: L = {L} m, mu = {mu} kg/m")
    print(f"Tension for f1 = {f1_target} Hz: T = {T:.3f} N\n")
    print(f"{'n':>3} {'f_n (Hz)':>12} {'ratio':>8}")
    for n, fn in enumerate(harm, start=1):
        print(f"{n:>3} {fn:>12.2f} {fn / f1_target:>8.0f}")

